INSERT INTO "odyle_sources" VALUES(1,'Odyle shop (per character)','shop','per_character',4.0,40.0,100000.0,1,1,'kr_tw_reference','provisional','Removed in KR S3 (pre-S3: 4 per character). KR S3: 21 per server per week at 100,000 Kinah each (pre-S3: 4/character + 12/server). On Global the Wind Breeze merchant is membership-only. https://www.inven.co.kr/board/aion2/6388/150348',0.0,0.0,0.0);
INSERT INTO "odyle_sources" VALUES(2,'Odyle shop (shared server)','shop','per_server',16.0,40.0,100000.0,1,1,'kr_tw_reference','provisional','KR S3: 21 per server per week at 100,000 Kinah each (pre-S3: 4/character + 12/server). On Global the Wind Breeze merchant is membership-only. https://www.inven.co.kr/board/aion2/6388/150348',0.0,0.0,0.0);
INSERT INTO "odyle_sources" VALUES(3,'Substance Morph (per character)','morph','per_character',4.0,40.0,50000.0,1,0,'kr_tw_reference','provisional','Removed in KR S3. KR S3: 20 per server per week; per-character recipe removed (launch: 7/character, 50,000 Kinah + 25 Odyle + 5 Pure Odyle + 1 Refined Pure Odyle → 40). https://www.gameple.co.kr/news/articleView.html?idxno=214580',25.0,5.0,1.0);
INSERT INTO "odyle_sources" VALUES(4,'Substance Morph (shared server)','morph','per_server',16.0,40.0,50000.0,1,0,'kr_tw_reference','provisional','KR S3: 20 per server per week; per-character recipe removed (launch: 7/character, 50,000 Kinah + 25 Odyle + 5 Pure Odyle + 1 Refined Pure Odyle → 40). https://www.gameple.co.kr/news/articleView.html?idxno=214580',25.0,5.0,1.0);
